set questions = $json$[{"id": "silverenv001_01", "type": "choice", "label": "When you think about this topic in your own life, how often does it feel emotionally ‘loaded’ rather than neutral?", "options": ["Almost always", "Often", "Sometimes", "Rarely", "Almost never"]}, {"id": "silverenv001_02", "type": "choice", "label": "How much do your answers here depend on your current life stage (care, dependents, income, health)?", "options": ["A great deal", "Quite a bit", "Somewhat", "A little", "Hardly at all"]}, {"id": "silverenv001_03", "type": "choice", "label": "Do you usually seek out disagreement on this topic, or prefer communities that largely agree with you?", "options": ["Seek disagreement", "Mix of both", "Prefer agreement", "Avoid the topic", "Not sure"]}, {"id": "silverenv001_04", "type": "choice", "label": "Which best describes your relationship to ‘expert’ voices on this topic?", "options": ["I defer to them", "I weigh them against experience", "I’m skeptical by default", "I ignore them", "It varies wildly"]}, {"id": "silverenv001_05", "type": "choice", "label": "If you had to choose, is this topic more about individual choices or systems and institutions?", "options": ["Mostly individual", "Lean individual", "Even split", "Lean systems", "Mostly systems"]}, {"id": "silverenv001_06", "type": "choice", "label": "How comfortable are you admitting uncertainty or changing your mind publicly about this?", "options": ["Very comfortable", "Somewhat", "Neutral", "Uncomfortable", "I avoid it"]}, {"id": "silverenv001_07", "type": "choice", "label": "When resources are scarce (time, money, attention), how do you usually decide what to protect first?", "options": ["Family or close ties", "Health or rest", "Work or income", "Principles or causes", "Something else"]}, {"id": "silverenv001_08", "type": "choice", "label": "How much does fear of being judged shape what you say about this topic in ordinary conversation?", "options": ["A great deal", "Quite a bit", "Somewhat", "A little", "Not much"]}, {"id": "silverenv001_09", "type": "text", "label": "Describe a recent moment when this topic forced you to choose between two values you both care about. What did you pick, and what did it cost?"}, {"id": "silverenv001_10", "type": "text", "label": "What is one widely repeated opinion about this topic that you think is too simple? What nuance is usually missing?"}, {"id": "silverenv001_11", "type": "text", "label": "If someone you respect disagreed with you on this, what is the strongest version of their argument you could offer on their behalf?"}, {"id": "silverenv001_12", "type": "choice", "label": "You can improve one thing in this domain with serious effort, or help three people in a smaller way. Which pulls you?", "options": ["The deep single improvement", "The broader smaller help", "I’d try to combine", "Refuse the frame", "Depends on who is affected"]}, {"id": "silverenv001_13", "type": "choice", "label": "A policy change would help many strangers but slightly inconvenience you weekly. Support it?", "options": ["Yes, strongly", "Yes, cautiously", "Need more detail", "Probably not", "No"]}, {"id": "silverenv001_14", "type": "choice", "label": "You discover a habit of yours has unintended harm you didn’t see before. What’s your first instinct?", "options": ["Change quickly", "Research more", "Feel guilty", "Rationalize", "Talk to someone"]}, {"id": "silverenv001_15", "type": "choice", "label": "How much do you weigh future people (you’ll never meet) in decisions that affect this topic today?", "options": ["A lot", "Some", "Unsure how to", "Rarely", "Not consciously"]}, {"id": "silverenv001_16", "type": "choice", "label": "When brands or leaders speak on this topic, what erodes your trust fastest?", "options": ["Vague virtue signaling", "Data overreach", "Hypocrisy", "Fear messaging", "Overpromising"]}, {"id": "silverenv001_17", "type": "choice", "label": "If you could only protect one—honesty, kindness, or effectiveness—which do you lean on when they conflict here?", "options": ["Honesty", "Kindness", "Effectiveness", "Refuse to rank", "Situational blend"]}, {"id": "silverenv001_18", "type": "choice", "label": "Do you experience this topic more as a private inner struggle or a public political fight?", "options": ["Mostly private", "More private", "Both equally", "More public", "Mostly public"]}, {"id": "silverenv001_19", "type": "choice", "label": "How often do you update your views based on new evidence vs. doubling down?", "options": ["Update often", "Sometimes update", "Slow to update", "Rarely update", "Depends on the source"]}, {"id": "silverenv001_20", "type": "choice", "label": "Which risk worries you more in this area: being exploited, or missing an opportunity to help?", "options": ["Being exploited", "Missing help", "Both equally", "Neither—different fears", "Not sure"]}, {"id": "silverenv001_21", "type": "text", "label": "Name one assumption people make about ‘people like you’ in this topic that is often wrong or incomplete."}, {"id": "silverenv001_22", "type": "text", "label": "What is a constructive disagreement you wish more people could have about this—without collapsing into teams?"}, {"id": "silverenv001_23", "type": "choice", "label": "After reflecting, how clear is your own position on this topic?", "options": ["Very clear", "Somewhat clear", "Mixed", "Uncertain", "Intentionally open"]}, {"id": "silverenv001_24", "type": "choice", "label": "Would you want a close friend to challenge you on this more often, less often, or about the same?", "options": ["More often", "About the same", "Less often", "Depends on how they do it", "Not sure"]}, {"id": "silverenv001_25", "type": "choice", "label": "How likely are you to seek new information on this in the next month?", "options": ["Very likely", "Likely", "Maybe", "Unlikely", "Very unlikely"]}, {"id": "silverenv001_26", "type": "choice", "label": "Do you feel more hopeful, more concerned, or about the same compared to a year ago?", "options": ["More hopeful", "About the same", "More concerned", "Both hopeful and concerned", "I avoid comparing"]}, {"id": "silverenv001_27", "type": "choice", "label": "If you could fund one type of project in this area, what would you pick?", "options": ["Education", "Infrastructure", "Research", "Direct aid", "Advocacy"]}, {"id": "silverenv001_28", "type": "choice", "label": "How much does community (online or offline) matter for how you think about this topic?", "options": ["Essential", "Important", "Moderate", "Minor", "I think alone"]}, {"id": "silverenv001_29", "type": "choice", "label": "Would you rather improve your own situation first, or work on collective change first?", "options": ["Own situation", "Collective change", "Both in parallel", "Refuse the split", "Context-dependent"]}, {"id": "silverenv001_30", "type": "choice", "label": "Final calibration: how representative do you think your answers are of people in situations very different from yours?", "options": ["Very representative", "Somewhat", "Not very", "I doubt it", "I actively don’t know"]}]$json$::jsonb
